cat > Cargo.toml <<'EOF'
[package]
name = "wintool"
version = "0.1.0"
edition = "2024"
publish = false

# Windows API bindings. Only pulled in when building for Windows.
# Enable additional `Win32_*` features as you need more of the API surface;
# see https://microsoft.github.io/windows-rs/features for the feature search.
[target.'cfg(windows)'.dependencies.windows]
version = "0.62"
features = [
    "Win32_Foundation",
    "Win32_System_SystemInformation",
    "Win32_System_Threading",
]

[profile.release]
lto = true
codegen-units = 1
strip = true
EOF
cat > src/main.rs <<'EOF'
#[cfg(not(windows))]
compile_error!("wintool only supports Windows targets (e.g. x86_64-pc-windows-msvc).");

use windows::Win32::System::SystemInformation::{
    ComputerNameDnsHostname, GetComputerNameExW,
};
use windows::Win32::System::Threading::GetCurrentProcessId;
use windows::core::PWSTR;

fn main() -> windows::core::Result<()> {
    let pid = unsafe { GetCurrentProcessId() };
    println!("pid:      {pid}");
    println!("hostname: {}", computer_name()?);
    Ok(())
}

/// Returns the DNS hostname of the local machine.
fn computer_name() -> windows::core::Result<String> {
    // First call with a null buffer to learn the required size (incl. NUL).
    let mut len = 0u32;
    let _ = unsafe { GetComputerNameExW(ComputerNameDnsHostname, None, &mut len) };

    let mut buf = vec![0u16; len as usize];
    unsafe { GetComputerNameExW(ComputerNameDnsHostname, Some(PWSTR(buf.as_mut_ptr())), &mut len)? };

    // On success, `len` is the number of characters written, excluding the NUL.
    Ok(String::from_utf16_lossy(&buf[..len as usize]))
}
EOF
cat > .gitignore <<'EOF'
/target
EOF
cargo check --target x86_64-pc-windows-gnu 2>&1 | tail -15

